{% extends 'base.html' %}

{% block title %}{{ outlet.name }} Menu{% endblock %}

{% block content %}

<div class="page-head">
    <div>
        <div class="eyebrow">CAMPUS MENU</div>
        <h1>{{ outlet.name }}</h1>
        <p class="muted">
            Prices and availability update from the outletâ€™s live menu.
        </p>
    </div>

    {% if outlet.menu_pdf %}
    <a class="button"
       href="{{ url_for('uploaded_file', filename=outlet.menu_pdf) }}">
        View menu PDF
    </a>
    {% endif %}
</div>

<div class="filters">
    <input id="search" placeholder="Search dishesâ€¦">

    <select id="category">
        <option value="">All categories</option>

        {% for c in categories %}
        <option value="{{ c.name }}">{{ c.name }}</option>
        {% endfor %}
    </select>
</div>


<div id="menu-container">

    {% for c in categories %}

    <section class="menu-section"
             data-category-section="{{ c.name }}">

        <div class="menu-section-heading">
            <h2>{{ c.name }}</h2>
        </div>

        <div class="grid">

            {% for m in items if m.category == c.name %}

            <article class="card menu-card"
                     data-name="{{ m.name|lower }}"
                     data-category="{{ m.category or 'General' }}">

                <div class="menu-top">

                    <span class="food-icon">ðŸ¥˜</span>

                    <span class="status {{ 'accepted' if m.available and m.stock > 0 else 'rejected' }}">
                        {{ 'Available' if m.available and m.stock > 0 else 'Unavailable' }}
                    </span>

                </div>

                <h3>{{ m.name }}</h3>

                <p>{{ m.description }}</p>

                <div class="menu-meta">
                    <strong>
                        â‚¹{{ '%.2f'|format(m.price_cents / 100) }}
                    </strong>

                    <span>
                        {{ m.prep_minutes }} min
                    </span>
                </div>

                {% if current_user.role == 'STUDENT' %}

                <form method="post"
                      action="{{ url_for('cart_add', item_id=m.id) }}">

                    <input type="hidden"
                           name="csrf_token"
                           value="{{ csrf_token }}">

                    <div class="add-row">

                        <input type="number"
                               name="quantity"
                               min="1"
                               max="99"
                               value="1"
                               aria-label="Quantity">

                        <button class="button primary"
                                {% if not m.available or m.stock == 0 %}
                                disabled
                                {% endif %}>
                            Add to cart
                        </button>

                    </div>

                </form>

                {% endif %}

            </article>

            {% endfor %}

        </div>

    </section>

    {% endfor %}

</div>


<script>

const search = document.querySelector("#search");
const category = document.querySelector("#category");

function filterMenu() {

    const searchText = search.value.toLowerCase();
    const selectedCategory = category.value;

    document.querySelectorAll(".menu-section").forEach(section => {

        const sectionCategory =
            section.dataset.categorySection;

        let visibleItems = 0;

        section.querySelectorAll(".menu-card").forEach(card => {

            const matchesSearch =
                card.dataset.name.includes(searchText);

            const matchesCategory =
                !selectedCategory ||
                sectionCategory === selectedCategory;

            const visible =
                matchesSearch && matchesCategory;

            card.style.display =
                visible ? "" : "block";

            if (visible) {
                visibleItems++;
            }

        });

        section.style.display =
            visibleItems > 0 ? "" : "none";
    });
}

search.addEventListener("input", filterMenu);
category.addEventListener("change", filterMenu);

</script>

{% endblock %}

