@app.route('/checkout',methods=['GET','POST'])
@login_required
@roles('STUDENT')
def checkout():
    db=get_db(); data=session.get('cart',{})
    if not data.get('items'): flash('Your cart is empty.','error'); return redirect(url_for('cart'))
    if request.method=='POST':
        if request.form.get('action')=='update_cart':
            # Update the session first, then render from fresh database
            # prices in this request so the checkout page reflects the
            # submitted quantities immediately.
            updated={}
            for iid in list(data.get('items',{})):
                try:
                    qty=int(request.form.get('qty_'+iid, 0))
                except (TypeError, ValueError):
                    qty=0
                if qty > 0:
                    updated[str(iid)]=min(99, qty)
            data['items']=updated
            if data['items']:
                session['cart']=data
            else:
                session.pop('cart', None)
                flash('Your cart is empty.','error')
                return redirect(url_for('cart'))
        method=request.form.get('payment_method'); paid=request.form.get('payment_result','success')
        if method not in ('MOCK_ONLINE','PAY_AT_PICKUP'): flash('Choose a valid payment method.','error')
        elif method=='MOCK_ONLINE' and paid!='success':
            notify(g.user['id'], 'Payment requires attention', 'Mock payment failed. Retry payment or choose Pay at Pickup.', 'payment'); db.commit()
            flash('Mock payment failed. Retry payment or choose Pay at Pickup. No order was created.','error')
        else:
            try:
                db.execute('BEGIN IMMEDIATE'); total=0; prep=0; rows=[]
                for iid,qty in data['items'].items():
                    row=db.execute('SELECT m.*,i.id inv_id,i.quantity stock FROM menu_items m LEFT JOIN inventory_items i ON i.id=m.inventory_id WHERE m.id=? AND m.outlet_id=? AND m.active=1 AND m.available=1',(iid,data['outlet_id'])).fetchone()
                    qty=int(qty)
                    if not row or row['stock'] is not None and row['stock']<qty: raise ValueError('An item became unavailable or has insufficient stock.')
                    total+=row['price_cents']*qty; prep=max(prep,row['prep_minutes']); rows.append((row,qty))
                number=next_order_number(db)
                cur=db.execute('INSERT INTO orders(order_number,user_id,outlet_id,status,payment_method,payment_status,total_cents,prep_minutes) VALUES(?,?,? ,?,?,?, ?,?)',(number,g.user['id'],data['outlet_id'],'PENDING',method,'PAID' if method=='MOCK_ONLINE' else 'PENDING',total,prep))
                oid=cur.lastrowid
                for row,qty in rows:
                    db.execute('INSERT INTO order_items(order_id,menu_item_id,item_name,quantity,unit_price_cents) VALUES(?,?,?,?,?)',(oid,row['id'],row['name'],qty,row['price_cents']))
                    if row['inv_id']:
                        before=db.execute('SELECT quantity,low_threshold,item_name FROM inventory_items WHERE id=?',(row['inv_id'],)).fetchone()
                        db.execute('UPDATE inventory_items SET quantity=quantity-?,updated_at=CURRENT_TIMESTAMP WHERE id=?',(qty,row['inv_id']))
                        db.execute('INSERT INTO inventory_adjustments(inventory_id,actor_id,delta,reason) VALUES(?,?,?,?)',(row['inv_id'],g.user['id'],-qty,'Order '+number))
                        if before['quantity']>before['low_threshold'] and before['quantity']-qty<=before['low_threshold']:
                            watchers=db.execute("SELECT id FROM users WHERE active=1 AND (role='ADMIN' OR outlet_id=? AND role IN ('STAFF','DH_MANAGER'))",(data['outlet_id'],)).fetchall()
                            for watcher in watchers: notify(watcher['id'],'Low stock',f'{before["item_name"]} is at or below its low-stock threshold.','inventory')
                staff=db.execute("SELECT id FROM users WHERE active=1 AND (role='ADMIN' OR outlet_id=? AND role IN ('STAFF','DH_MANAGER'))",(data['outlet_id'],)).fetchall()
                for s in staff: notify(s['id'],'New order',f'Order {number} is waiting for review.','order',oid)
                payment_message='Payment is due at pickup.' if method=='PAY_AT_PICKUP' else 'Payment completed successfully.'
                notify(g.user['id'],'Order placed',f'Order {number} was placed successfully. {payment_message}','order',oid)
                audit(g.user['id'],'ORDER_CREATE','order',oid,number); db.commit(); session.pop('cart',None); return redirect(url_for('order_detail',order_id=oid))
            except (ValueError,sqlite3.Error) as e:
                db.rollback(); flash(str(e) if isinstance(e,ValueError) else 'Could not place order. Please try again.','error')
    lines=[]; total=0
    for iid,q in data['items'].items():
        row=db.execute('SELECT * FROM menu_items WHERE id=? AND outlet_id=? AND active=1',(iid,data['outlet_id'])).fetchone()
        if row: lines.append((row,int(q))); total+=row['price_cents']*int(q)

