mpty">No menu items are available yet.</div>{% endfor %}</div><script>const s=document.querySelector('#search'),c=document.querySelector('#category');function filter(){document.querySelectorAll('.menu-section').forEach(section=>{const matchesCategory=!c.value||section.dataset.categorySection===c.value;let visible=0;section.querySelectorAll('.menu-card').forEach(card=>{const show=matchesCategory&&card.dataset.name.includes(s.value.toLowerCase());card.hidden=!show;if(show)visible++});section.hidden=visible===0})}s.oninput=filter;c.onchange=filter;</script>{% endblock %}
